// Helper to look up an application by ID or Code
export const getMandelaAppById = (appId: string): MandelaApplication | undefined => {
  return MANDELA_APPLICATIONS.find(
    (app) => app.id === appId || app.code.toLowerCase() === appId.toLowerCase()
  );
};

// Helper to get applications by tier
export const getMandelaAppsByTier = (tier: OperatingSystemTier): MandelaApplication[] => {
  return MANDELA_APPLICATIONS.filter((app) => app.tier === tier);
};
